/**
 * Adds mythology stories for festivals that currently have zero linked
 * stories_index rows (checked via parent_slug + parent_type='festival').
 *
 * Append-only: refuses to write a stories_index row if the slug already
 * exists, and refuses to write stories_content rows for a (slug, lang) pair
 * that already has content. Dry-run by default; pass --write to apply.
 *
 * Festivals are processed one at a time across separate runs, add the next
 * entry to STORIES only after the previous one has been reviewed and applied.
 *
 * Usage:
 *   node scripts/upload-avatar-festival-stories.mjs          (dry run)
 *   node scripts/upload-avatar-festival-stories.mjs --write  (apply)
 */
import { getSheetsClient, SPREADSHEET_ID as SHEET_ID, parseWriteFlag, getTabWithHeaders } from './lib-sheets.mjs';

