console.log(`\n══ upload-avatar-festival-stories.mjs ══════════════════════════════`);
console.log(`Mode: ${WRITE ? '⚡ WRITE' : '🔍 DRY RUN (pass --write to apply)'}`);

const { rows: indexRows, col: indexCol } = await getTabWithHeaders('stories_index');
const { rows: contentRows, col: contentCol } = await getTabWithHeaders('stories_content');

const iSlug = indexCol('slug');
const cSlug = contentCol('story_slug');
const cLang = contentCol('lang');

const existingIndexSlugs = new Set(indexRows.map(r => r[iSlug]));
const existingContentPairs = new Set(contentRows.map(r => `${r[cSlug]}::${r[cLang]}`));

const indexAppendRows = [];
const contentAppendRows = [];
let warnings = 0;

for (const story of STORIES) {
  console.log(`\n── ${story.slug} (parent: ${story.parent_slug}) ──`);

  if (existingIndexSlugs.has(story.slug)) {
    console.log(`  ⚠️  WARNING: stories_index already has slug "${story.slug}", skipping index row.`);
    warnings++;
  } else {
    // slug, title_en, title_te, title_ta, title_hi, deity_slug, story_type,
    // source_scripture_en, reading_instruction_en, brief_summary_en/te/ta/hi,
    // gdoc_id_en/te/ta/hi, status, translation_status, parent_slug, parent_type
    indexAppendRows.push([
      story.slug,
      story.title.en, story.title.te, story.title.ta, story.title.hi,
      story.deity_slug,
      story.story_type,
      story.source_scripture_en,
      story.reading_instruction_en,
      story.brief_summary.en, story.brief_summary.te, story.brief_summary.ta, story.brief_summary.hi,
      '', '', '', '', // gdoc_id_en/te/ta/hi left empty
      'published',
      'complete',
      story.parent_slug,
      'festival',
    ]);
    console.log(`  APPEND stories_index row: title_en="${story.title.en}"`);
  }

  for (const lang of LANGS) {
    const pairKey = `${story.slug}::${lang}`;
    if (existingContentPairs.has(pairKey)) {
      console.log(`  ⚠️  WARNING: stories_content already has rows for (${story.slug}, ${lang}), skipping.`);
      warnings++;
      continue;
    }
    const paragraphs = story.content[lang];
    paragraphs.forEach((text, i) => {
      const paragraphNum = i + 1;
      contentAppendRows.push([story.slug, lang, String(paragraphNum), text]);
    });
    console.log(`  APPEND stories_content: lang=${lang}, ${paragraphs.length} paragraphs`);
  }
}

console.log(`\n── Summary ───────────────────────────────────────────────────────`);
console.log(`stories_index rows to append   : ${indexAppendRows.length}`);
console.log(`stories_content rows to append : ${contentAppendRows.length}`);
console.log(`Warnings (skipped, already exists): ${warnings}`);

if (!WRITE) {
  console.log(`\nDry run. Pass --write to apply.`);
  process.exit(0);
}

const sheets = await getSheetsClient();

if (indexAppendRows.length > 0) {
  await sheets.spreadsheets.values.append({
    spreadsheetId: SHEET_ID,
    range: 'stories_index!A:U',
    valueInputOption: 'RAW',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: indexAppendRows },
  });
  console.log(`\n✓ Appended ${indexAppendRows.length} rows to stories_index`);
}

if (contentAppendRows.length > 0) {
  await sheets.spreadsheets.values.append({
    spreadsheetId: SHEET_ID,
    range: 'stories_content!A:D',
    valueInputOption: 'RAW',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: contentAppendRows },
  });
  console.log(`✓ Appended ${contentAppendRows.length} rows to stories_content`);
}

console.log(`\n✓ Done.`);
